﻿{
  "schema": "loom.application_profile/1",
  "id": "synthetic-arbitrary-app-3.7",
  "profile_revision": 1,
  "label": "Synthetic arbitrary app 3.7",
  "target": {
    "application_id": "synthetic-any-application",
    "version": "ui-release-3.7",
    "platform": "web"
  },
  "evidence": {
    "status": "partial",
    "sources": [],
    "gaps": [
      "Synthetic editable profile; no external application fidelity claim."
    ]
  },
  "presentation": {
    "renderer": "chat",
    "tokens": {
      "background": "#0f0f14",
      "surface": "#24242e",
      "text": "#f2f2f2",
      "muted": "#8c8c99",
      "accent": "#4d8cf2",
      "border": "#33333e"
    },
    "sidebar": {
      "side": "right",
      "width": 240
    },
    "content_width": 610,
    "message_style": "bubble"
  },
  "composer": {
    "submit": "mod-enter",
    "placeholder": "Custom application composer"
  },
  "actions": [
    {
      "id": "original-send-gap",
      "label": "Original service Send unavailable",
      "operation": "chat.send",
      "capability": "original.chat.send",
      "required": false
    },
    {
      "id": "create",
      "label": "New conversation",
      "operation": "chat.create",
      "capability": "chat.create",
      "required": true
    },
    {
      "id": "select",
      "label": "Return to conversation",
      "operation": "chat.select",
      "capability": "chat.select",
      "required": true
    },
    {
      "id": "send",
      "label": "Send",
      "operation": "chat.send",
      "capability": "chat.send",
      "required": true
    },
    {
      "id": "cancel",
      "label": "Stop",
      "operation": "chat.cancel",
      "capability": "chat.cancel",
      "required": true
    },
    {
      "id": "edit",
      "label": "Edit message",
      "operation": "message.edit",
      "capability": "message.edit",
      "required": true
    },
    {
      "id": "restore",
      "label": "Restore version",
      "operation": "message.restore",
      "capability": "message.restore",
      "required": true
    },
    {
      "id": "exclude",
      "label": "Exclude message",
      "operation": "message.exclude",
      "capability": "message.exclude",
      "required": true
    },
    {
      "id": "knowledge",
      "label": "Inspect knowledge",
      "operation": "knowledge.open",
      "capability": "knowledge.open",
      "required": false
    },
    {
      "id": "memory",
      "label": "Memory",
      "operation": "memory.open",
      "capability": "memory.open",
      "required": false
    },
    {
      "id": "import",
      "label": "Import",
      "operation": "import.open",
      "capability": "import.open",
      "required": false
    },
    {
      "id": "settings",
      "label": "Settings",
      "operation": "settings.open",
      "capability": "settings.open",
      "required": false
    }
  ],
  "workflows": [
    {
      "id": "conversation-review",
      "initial": "ready",
      "states": [
        "ready",
        "chat",
        "review"
      ],
      "transitions": [
        {
          "from": "ready",
          "event": "create",
          "action": "create",
          "to": "chat",
          "payload": {
            "object": {
              "title": {
                "literal": "Profile conversation"
              }
            }
          },
          "save": {
            "conversation_id": {
              "from": "result",
              "pointer": "/id"
            }
          }
        },
        {
          "from": "chat",
          "event": "inspect",
          "action": "knowledge",
          "to": "review",
          "payload": {
            "object": {}
          }
        },
        {
          "from": "review",
          "event": "return",
          "action": "select",
          "to": "chat",
          "payload": {
            "object": {
              "id": {
                "from": "vars",
                "pointer": "/conversation_id"
              }
            }
          }
        }
      ]
    }
  ]
}

